const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const data=[['Travel','TRAVEL','Abu Dhabi travel company','Client-specific challenge to be added.','Performance acquisition, lead generation and growth.'],['Wellness & Spa','WELLNESS','Wellness & spa','Client-specific challenge to be added.','Local lead generation, Google Ads, Meta Ads and conversion systems.'],['Home Repair','REPAIR','Home repair services','Client-specific challenge to be added.','High-intent search campaigns and local lead generation.'],['Aviation Parts','AVIATION','Aviation parts suppliers','Client-specific challenge to be added.','B2B marketing and lead generation.'],['Healthcare','HEALTH','Healthcare services','Client-specific challenge to be added.','Patient acquisition, search marketing and local growth.'],['E-Commerce','COMMERCE','E-commerce brands','Client-specific challenge to be added.','Performance campaigns, ROAS and conversion optimization.']];
let selected=0,cardAnimation;const industry=document.querySelector('.industries'),casePanel=document.querySelector('#case');
data.forEach((d,i)=>{const b=document.createElement('button');b.innerHTML='<span class="industry-number">0'+(i+1)+'</span><span>'+d[0]+'</span><span class="industry-arrow" aria-hidden="true">↗</span>';b.id='industry-'+i;b.setAttribute('role','tab');b.setAttribute('aria-controls','case');b.addEventListener('click',()=>select(i));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();select(e.key==='Home'?0:e.key==='End'?5:(selected+(['ArrowRight','ArrowDown'].includes(e.key)?1:5))%6);industry.children[selected].focus();}});industry.append(b)});
function openCard(){if(reduced)return;if(cardAnimation)cardAnimation.cancel();const compact=matchMedia('(max-width:800px)').matches;cardAnimation=casePanel.animate([{transform:'translate('+ (compact?'-14%':'-44%') +', 21%) rotate(-14deg) rotateY(-24deg) scale(.48)',opacity:0,filter:'brightness(.65)'},{offset:.3,transform:'translate(-15%, 8%) rotate(-6deg) rotateY(-12deg) scale(.72)',opacity:1,filter:'brightness(.85)'},{transform:'translate(0,0) rotate(0deg) rotateY(0deg) scale(1)',opacity:1,filter:'brightness(1)'}],{duration:1350,easing:'cubic-bezier(.18,.75,.2,1)',fill:'none'});}
function select(i,animate=true){const next=(i+6)%6;if(next===selected&&animate)return;selected=next;const d=data[selected];[...industry.children].forEach((b,j)=>{b.setAttribute('aria-selected',j===selected);b.tabIndex=j===selected?0:-1});casePanel.setAttribute('aria-labelledby','industry-'+selected);casePanel.dataset.industry=selected;document.querySelector('.case-no').textContent='0'+(selected+1)+' / 06';document.querySelector('.case-word').textContent=d[1];document.querySelector('#case-title').textContent=d[2];document.querySelector('#strategy').textContent=d[4];document.querySelector('#industry-status').textContent='0'+(selected+1)+' / 06 — '+d[0];if(animate)openCard();}
select(0,false);document.querySelector('#prev').onclick=()=>select(selected-1);document.querySelector('#next').onclick=()=>select(selected+1);
let dragStart;const caseVisual=document.querySelector('.case-visual');caseVisual.addEventListener('pointerdown',e=>{dragStart=e.clientX;caseVisual.setPointerCapture(e.pointerId)});caseVisual.addEventListener('pointerup',e=>{if(dragStart!==undefined&&Math.abs(e.clientX-dragStart)>45)select(selected+(e.clientX<dragStart?1:-1));dragStart=undefined});caseVisual.addEventListener('pointercancel',()=>dragStart=undefined);
const cardEntrance=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){openCard();cardEntrance.disconnect()}},{threshold:.3});cardEntrance.observe(document.querySelector('.industry-stage'));
const funnel=document.querySelector('.funnel');['Ad impression','Click','Landing page','Lead','CRM','Follow-up','Sale','Remarketing'].forEach((s,i)=>{const d=document.createElement('div');d.style.width=(100-i*5)+'%';d.innerHTML=`${s.toUpperCase()} <small>0${i+1}</small>`;funnel.append(d)});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{e.target.classList.toggle('active',e.isIntersecting);if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.6});document.querySelectorAll('.reveal,.funnel div,.steps article').forEach(e=>observer.observe(e));window.addEventListener('scroll',()=>document.querySelector('header').classList.toggle('scrolled',scrollY>30),{passive:true});document.querySelectorAll('.node').forEach(n=>n.addEventListener('click',()=>{document.querySelectorAll('.node').forEach(b=>b.classList.remove('active'));n.classList.add('active');document.querySelector('#node-info').textContent=n.dataset.info}));
const cursor=document.querySelector('#cursor');if(matchMedia('(pointer:fine)').matches&&!reduced){document.addEventListener('pointermove',e=>{cursor.style.display='flex';cursor.style.left=e.clientX+'px';cursor.style.top=e.clientY+'px';let t=e.target.closest('[data-cursor],a,button');cursor.classList.toggle('expanded',!!t);cursor.querySelector('span').textContent=t?(t.dataset.cursor||'OPEN'):''});document.addEventListener('pointerleave',()=>cursor.style.display='none')}
const wrap=document.querySelector('.portrait-wrap'),img=document.querySelector('#portrait'),canvas=document.querySelector('#dissolve'),ctx=canvas.getContext('2d');let base=document.createElement('canvas'),bctx=base.getContext('2d'),mask=document.createElement('canvas'),mctx=mask.getContext('2d');let holes=[],particles=[],pointer=null,last=0,visible=true;
function prepare(){if(!img.naturalWidth||!wrap.clientWidth)return;const w=Math.min(1000,Math.round(wrap.clientWidth*Math.min(devicePixelRatio,1.5))),h=Math.round(w*wrap.clientHeight/wrap.clientWidth);[canvas,base,mask].forEach(c=>{c.width=w;c.height=h});const scale=Math.min(w/img.naturalWidth,h/img.naturalHeight),iw=img.naturalWidth*scale,ih=img.naturalHeight*scale;bctx.clearRect(0,0,w,h);bctx.drawImage(img,(w-iw)/2,(h-ih)/2,iw,ih);wrap.classList.add('ready');ctx.drawImage(base,0,0);}
function locate(e){const r=canvas.getBoundingClientRect();pointer={x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};}wrap.addEventListener('pointermove',locate);wrap.addEventListener('pointerdown',locate);wrap.addEventListener('pointerleave',()=>{pointer=null;wrap.style.setProperty('--portrait-x','0px');wrap.style.setProperty('--portrait-y','0px')});wrap.addEventListener('pointerup',e=>{if(e.pointerType!=='mouse')pointer=null});new IntersectionObserver(e=>visible=e[0].isIntersecting).observe(wrap);
function frame(t){requestAnimationFrame(frame);if(!visible||reduced||t-last<30)return;let dt=Math.min((t-last)/1000,.05);last=t;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(base,0,0);if(pointer){holes.push({...pointer,life:1});for(let i=0;i<4;i++){let a=Math.random()*Math.PI*2;particles.push({x:pointer.x,y:pointer.y,vx:Math.cos(a)*(25+Math.random()*70),vy:Math.sin(a)*65-15,life:1,size:Math.random()*2+.5,green:Math.random()>.5})}}holes=holes.filter(p=>p.life>0).slice(-80);ctx.globalCompositeOperation='destination-out';for(const p of holes){p.life-=dt*.65;let g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,53);g.addColorStop(0,`rgba(0,0,0,${Math.min(1,p.life*2)})`);g.addColorStop(1,'transparent');ctx.fillStyle=g;ctx.fillRect(p.x-53,p.y-53,106,106)}ctx.globalCompositeOperation='source-over';particles=particles.filter(p=>p.life>0).slice(-350);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt*.7;ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.green?'#b6ff00':'#f4f4f4';ctx.fillRect(p.x,p.y,p.size,p.size);if(p.size>2){ctx.fillRect(p.x-2,p.y+.5,6,1);ctx.fillRect(p.x+.5,p.y-2,1,6)}}ctx.globalAlpha=1;}
if(img.complete&&img.naturalWidth)prepare();else img.addEventListener('load',prepare);if(!reduced)requestAnimationFrame(frame);let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(prepare,200)});
const space=document.querySelector('#space'),sctx=space.getContext('2d');let stars=[];function sizeSpace(){space.width=space.clientWidth;space.height=space.clientHeight;stars=Array.from({length:innerWidth<800?40:90},()=>({x:Math.random()*space.width,y:Math.random()*space.height,r:Math.random()*1.2+.2,s:Math.random()*10}));}sizeSpace();window.addEventListener('resize',sizeSpace);function paintSpace(t){sctx.clearRect(0,0,space.width,space.height);stars.forEach(s=>{sctx.fillStyle=`rgba(189,213,153,${.2+Math.sin(t*.0003+s.s)*.2})`;sctx.fillRect(s.x,s.y,s.r,s.r)});if(!reduced)setTimeout(()=>requestAnimationFrame(paintSpace),65)}paintSpace(0);

if(!reduced&&matchMedia('(pointer:fine)').matches){document.querySelector('.hero').addEventListener('pointermove',e=>{const r=wrap.getBoundingClientRect();wrap.style.setProperty('--portrait-x',((e.clientX-innerWidth/2)/innerWidth*9)+'px');wrap.style.setProperty('--portrait-y',((e.clientY-r.top-r.height/2)/innerHeight*5)+'px')});}
